const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextToken() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        const start = pos;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            pos++;
        }
        return input.slice(start, pos);
    }

    const nToken = nextToken();
    if (!nToken) return;
    const N = parseInt(nToken, 10);
    const D = parseFloat(nextToken());

    const P = new Float64Array(N + 1);
    const C = new Float64Array(N);

    for (let i = 0; i < N; i++) {
        P[i] = parseFloat(nextToken());
        C[i] = parseFloat(nextToken());
    }
    P[N] = D;

    const dp = new Float64Array(N + 1);
    dp.fill(Infinity);
    dp[0] = 0;

    for (let i = 0; i < N; i++) {
        const curDist = P[i];
        const curCharge = C[i];
        const curTime = dp[i];

        for (let j = i + 1; j <= N; j++) {
            const d = P[j] - curDist;
            const t = (d * d) / curCharge;
            if (curTime + t < dp[j]) {
                dp[j] = curTime + t;
            }
        }
    }

    console.log(dp[N].toFixed(3));
}

main();
